CLAIM_CHECK_ROOTS = tuple(
    f"fundamentals.ledger.{name}"
    for name in ("claim_check", "citations", "numeral_scan", "lifecycle")
)

def _seed_bytes(relative: str) -> bytes:
    return subprocess.run(
        ["git", "-C", str(REPO_ROOT), "show", f"{SEED_COMMIT}:src/fundamentals/{relative}"],
        check=True,
        capture_output=True,
    ).stdout
